MODULE_TEXT="import json\nfrom decimal import Decimal, InvalidOperation\nfrom datetime import datetime, timezone\nfrom zoneinfo import ZoneInfo\n\nZERO = Decimal('0')\ndef dec(value):\n    try:\n        x=Decimal(str(value))\n        return x if x.is_finite() else None\n    except (InvalidOperation,ValueError,TypeError): return None\n\ndef scalar(x): return str(x) if x is not None else None\n\ndef amount(o,crypto):\n    n=dec(o.get('net_rounded_executed_notional'))\n    if n is not None and n>0: return n\n    if crypto: return None\n    q,p,f=dec(o.get('cumulative_quantity')),dec(o.get('average_price')),dec(o.get('fees'))\n    if None in (q,p,f): return None\n    return q*p+f if o.get('side')=='buy' else q*p-f\n\ndef fee(o):\n    f=dec(o.get('fee'))\n    if f is not None:return f\n    return dec(o.get('fees')) if not isinstance(o.get('fees'),list) else None\n\ndef calculate(bot, crypto, exit_rate, today):\n    orders=bot.get('orders',[])\n    lots={}; closed=[]; seen=set(); warnings=[]\n    for o in sorted(orders,key=lambda x:x.get('created_at','')):\n        oid=o.get('id')\n        if not oid:\n            warnings.append('Order without ID excluded');continue\n        if oid in seen:continue\n        seen.add(oid)\n        q=dec(o.get('cumulative_quantity'))\n        if q is None or q<=0:continue\n        if o.get('state') not in ('filled','canceled','cancelled','partially_filled_rest_cancelled'):\n            warnings.append('Nonterminal filled quantity excluded from closed-trade reconstruction');continue\n        symbol=o.get('currency_code') or o.get('symbol')\n        side=o.get('side'); cash=amount(o,crypto)\n        if not symbol or side not in ('buy','sell'):\n            warnings.append('Order has missing asset or side');continue\n        queue=lots.setdefault(symbol,[])\n        if side=='buy':\n            queue.append({'q':q,'cost':cash,'fee':fee(o),'date':o.get('created_at')})\n            continue\n        left=q; cost=ZERO; bf=ZERO; known=True; fee_known=True; dates=[]\n        while left>0 and queue:\n            lot=queue[0]; take=min(left,lot['q']); fraction=take/lot['q']\n            if lot['cost'] is None:known=False\n            else:\n                used=lot['cost']*fraction;cost+=used;lot['cost']-=used\n            if lot['fee'] is None:fee_known=False\n            else:\n                used=lot['fee']*fraction;bf+=used;lot['fee']-=used\n            dates.append(lot['date']);lot['q']-=take;left-=take\n            if lot['q']==0:queue.pop(0)\n        known=known and left==0\n        net=cash-cost if known and cash is not None else None\n        closed.append({'asset':symbol,'buy_date':' / '.join(dict.fromkeys(d for d in dates if d)) if left==0 else 'Unmatched acquisition',\n          'sell_date':o.get('created_at'),'quantity':scalar(q),\n          'actual_price':scalar(cost/q) if known else None,\n          'sold_price':o.get('average_price'),\n          'net_per_unit':scalar(net/q) if net is not None else None,\n          'net_pct':scalar(net/cost*100) if net is not None and cost>0 else None,\n          'actual_total':scalar(cost) if known else None,'sold_total':scalar(cash),\n          'buy_fee':scalar(bf) if fee_known and left==0 else None,'sell_fee':scalar(fee(o)),\n          'net':scalar(net),'status':'FIFO reconstruction' if net is not None else 'Unreconciled',\n          'sell_id':oid})\n    positions=[]\n    quotes={str(x.get('symbol','')).replace('-',''):x for x in bot.get('quotes',[])}\n    for p in bot.get('positions',[]):\n        symbol=(p.get('currency') or {}).get('code') or p.get('symbol')\n        q=dec(p.get('quantity'))\n        if q is None or q<=0:continue\n        queue=lots.get(symbol,[]); tracked=sum((x['q'] for x in queue),ZERO)\n        valid_lots=tracked==q and all(x['cost'] is not None for x in queue)\n        cost=sum((x['cost'] for x in queue),ZERO) if valid_lots else None\n        cost_source='FIFO net acquisition debits' if cost is not None else 'Unavailable'\n        if cost is None:\n            bases=p.get('cost_bases') or []\n            if crypto and len(bases)==1:\n                b=bases[0];dq=dec(b.get('direct_quantity'));dc=dec(b.get('direct_cost_basis'))\n                if dq==q and dc is not None and dc>0:\n                    cost=dc;cost_source='Broker cost basis; fee inclusion not independently verified'\n            elif not crypto:\n                avg=dec(p.get('average_buy_price'))\n                if avg is not None and avg>0:cost=q*avg;cost_source='Broker average acquisition cost'\n        quote=quotes.get(str(symbol)+'USD',{}) if crypto else {}\n        price=dec(quote.get('mark_price'));bid=dec(quote.get('bid_price'));ask=dec(quote.get('ask_price'))\n        stamp=quote.get('updated_at');fresh=False\n        try:\n            age=(datetime.now(timezone.utc)-datetime.fromisoformat(stamp.replace('Z','+00:00'))).total_seconds()\n            fresh=0<=age<=180\n        except (TypeError,ValueError,AttributeError):pass\n        if not fresh or price is None or price<=0 or bid is None or ask is None or bid<=0 or ask<=0 or bid>ask:\n            price=None\n        value=q*price if price is not None else None\n        estimated_exit=value*exit_rate if value is not None and exit_rate is not None else None\n        net=value-cost-estimated_exit if None not in (value,cost,estimated_exit) else None\n        positions.append({'asset':symbol,'quantity':scalar(q),\n          'buy_date':' / '.join(dict.fromkeys(x['date'] for x in queue if x['date'])) if valid_lots else 'Unavailable',\n          'actual_price':scalar(cost/q) if cost is not None else None,'current_price':scalar(price),\n          'net_per_unit':scalar(net/q) if net is not None else None,\n          'net_pct':scalar(net/cost*100) if net is not None and cost>0 else None,\n          'actual_total':scalar(cost),'current_total':scalar(value),'net':scalar(net),\n          'estimated_exit_fee':scalar(estimated_exit),'quote_at':stamp,\n          'cost_source':cost_source,'status':'Estimated net; planning exit-fee assumption' if net is not None else 'Missing usable quote, basis, or exit-cost assumption'})\n    todays=[t for t in closed if (t['sell_date'] or '')[:10]==today]\n    realized=sum((dec(t['net']) for t in todays),ZERO) if all(t['net'] is not None for t in todays) else None\n    unrealized=sum((dec(p['net']) for p in positions),ZERO) if all(p['net'] is not None for p in positions) else None\n    current=realized+unrealized if realized is not None and unrealized is not None else None\n    return {'status':bot.get('status'),'fetched_at':bot.get('fetched_at'),'report_date':today,\n      'scope':'Selected asset class in brokerage account; includes manual activity, not bot-attributed',\n      'method':'FIFO reconstruction from loaded broker history; not broker tax-lot reconciliation',\n      'exit_fee_rate_assumption':scalar(exit_rate),'positions':positions,'trades':closed,\n      'summary':{'realized':scalar(realized),'unrealized':scalar(unrealized),'current':scalar(current),\n       'completed_sales_today':len(todays)},'warnings':list(dict.fromkeys(warnings))}\n\ndef build(snapshot):\n    today=datetime.now(ZoneInfo('America/New_York')).date().isoformat()\n    rate=None\n    try:\n        with open('/etc/si-crypto-r1/config.json') as f:rate=dec(json.load(f).get('fee_allowance_per_side'))\n        if rate is not None and not ZERO<=rate<1:rate=None\n    except (OSError,ValueError,TypeError):pass\n    return {'version':2,'bots':{name:calculate(bot,name=='crypto',rate if name=='crypto' else None,today)\n        for name,bot in snapshot.get('bots',{}).items() if name in ('crypto','equity')}}\n"
JS="<script>\n/* SI_ACCOUNTING_DIRECT_V2 */\n(()=>{'use strict';\nlet latest=null,problem='Waiting for broker accounting snapshot';\nconst $=id=>document.getElementById(id);\nconst fmt=(v,unit=false)=>v===null||v===undefined?'Unavailable':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:unit?6:2}).format(Number(v));\nconst pct=v=>v===null||v===undefined?'Unavailable':Number(v).toFixed(2)+'%';\nconst add=(p,t,s)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;p.append(n);return n;};\nfunction fill(table,headers,rows){\n table.replaceChildren();const head=add(table,'thead'),tr=add(head,'tr');headers.forEach(h=>add(tr,'th',h));const body=add(table,'tbody');\n if(!rows.length){const td=add(add(body,'tr'),'td','No records in the current snapshot.');td.colSpan=headers.length;}\n rows.forEach(values=>{const row=add(body,'tr');values.forEach(v=>{const c=add(row,'td',v??'Unavailable');if(String(v).startsWith('-$'))c.style.color='#b91c1c';});});\n}\nfunction paint(){\n const id=typeof selected==='string'?selected:'crypto';\n const scope=$('dashboard-page');if(!scope)return;\n let note=$('si-accounting-note');if(!note){note=add(scope,'p');note.id='si-accounting-note';note.className='notice';}\n const model=latest?.accounting_v2?.bots?.[id];\n const boxes=[...scope.querySelectorAll('.metrics > .box')];\n const labels=['Realized net — sales today (FIFO)','Est. unrealized net — open holdings','Est. current net — realized + open'];\n boxes.slice(1,4).forEach((b,i)=>{b.querySelector('.label').textContent=labels[i];b.querySelector('.value').textContent='Unavailable';});\n const pt=$('positions-page')?.querySelector('table'),tt=$('trades-page')?.querySelector('table');\n if(!model||problem){note.textContent=problem||'No accounting feed for '+id; if(pt)fill(pt,['Status'],[[note.textContent]]);if(tt)fill(tt,['Status'],[[note.textContent]]);return;}\n const age=(Date.now()-Date.parse(model.fetched_at))/1000;\n const healthy=model.status==='READ_OK'&&Number.isFinite(age)&&age>=0&&age<=300;\n const s=model.summary;\n boxes.slice(1,4).forEach((b,i)=>{const v=[s.realized,s.unrealized,s.current][i];b.querySelector('.value').textContent=fmt(v)+(healthy?'':' · stale');});\n note.textContent=(healthy?'Snapshot available. ':'STALE / READ FAILED — last-known figures only. ')+\n 'Scope: '+model.scope+'. Broker snapshot: '+model.fetched_at+'. Realized sale-date filter: '+model.report_date+' (US Eastern). '+model.method+'. '+\n 'Open net uses mark value less acquisition cost and estimated exit fees at '+(model.exit_fee_rate_assumption===null?'an unavailable rate':(Number(model.exit_fee_rate_assumption)*100).toFixed(2)+'%')+\n '; this is a planning assumption, not a broker-confirmed liquidation amount. Current net combines today’s realized result with all current open-position estimates; it is not daily account return. '+model.warnings.join('; ');\n if(pt){$('positions-title').textContent=(id==='crypto'?'Crypto':'US Equity')+' · Existing Positions';fill(pt,\n ['Asset','Buy Date','Quantity','Actual Price / Unit','Current Price / Unit (as of quote)','Est. Net P&L / Unit','Est. Net P&L %','Total Actual Cost','Total Current Value','Est. Total Net P&L','Est. Exit Fee','Quote Timestamp','Basis / Status'],\n model.positions.map(p=>[p.asset,p.buy_date,p.quantity,fmt(p.actual_price,true),fmt(p.current_price,true),fmt(p.net_per_unit,true),pct(p.net_pct),fmt(p.actual_total),fmt(p.current_total),fmt(p.net),fmt(p.estimated_exit_fee),p.quote_at,p.cost_source+'; '+p.status]));}\n if(tt){$('trades-title').textContent=(id==='crypto'?'Crypto':'US Equity')+' · Completed Trade Results — FIFO';fill(tt,\n ['Asset','Buy Date','Sell Date','Matched Quantity','Actual Price / Unit (net cost)','Sold Price / Unit (fill)','Net P&L / Unit','Net P&L %','Total Actual Cost (net debit)','Total Sold Value (net credit)','Total Net P&L','Buy Fee (already included)','Sell Fee (already included)','Status'],\n [...model.trades].reverse().map(t=>[t.asset,t.buy_date,t.sell_date,t.quantity,fmt(t.actual_price,true),fmt(t.sold_price,true),fmt(t.net_per_unit,true),pct(t.net_pct),fmt(t.actual_total),fmt(t.sold_total),fmt(t.net),fmt(t.buy_fee),fmt(t.sell_fee),t.status]));\n let raw=$('si-raw-order-history');if(!raw){raw=add($('trades-page'),'details');raw.id='si-raw-order-history';add(raw,'summary','Raw broker order history — separate from matched results');add(raw,'table');}\n const source=latest.bots[id];fill(raw.querySelector('table'),['Created','Asset','Side','State','Filled Quantity','Average Fill','Actual Net Debit / Credit','Reported Fee'],(source.orders||[]).map(o=>[o.created_at,o.currency_code||o.symbol,o.side,o.state,o.cumulative_quantity,fmt(o.average_price,true),fmt(o.net_rounded_executed_notional),fmt(o.fee??(Array.isArray(o.fees)?null:o.fees))]));}\n document.querySelectorAll('#dashboard-page .detail-row').forEach(row=>{\n const cells=row.querySelectorAll('span');if(cells.length!==2)return;\n const key=cells[0].textContent.toLowerCase();\n if(key.includes('realized')&&!key.includes('unrealized'))cells[1].textContent=fmt(s.realized);\n else if(key.includes('unrealized'))cells[1].textContent=fmt(s.unrealized);\n });\n}\nconst originalRender=render;render=function(){originalRender();try{paint();}catch(e){console.error('Accounting renderer',e);}};\nasync function refreshAccounting(){try{const r=await fetch('/api/v1/live',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.accounting_v2?.version!==2)throw Error('Collector accounting snapshot not ready');latest=d;problem='';}catch(e){problem='Accounting unavailable: '+e.message;}paint();}\nrefreshAccounting();setInterval(refreshAccounting,15000);\n})();\n</script>"
QUOTES='                        # SI_ACCOUNTING_QUOTES_V2\n                        quotes = []\n                        quote_error = None\n                        if crypto and safe_positions:\n                            try:\n                                qt = tools.get("getcryptoquotes")\n                                if not qt:\n                                    raise RuntimeError("Missing quote read tool")\n                                qs = qt.get("inputSchema", qt.get("input_schema"))\n                                props = qs.get("properties", {})\n                                symbols = sorted({p["currency"]["code"] + "-USD"\n                                    for p in safe_positions\n                                    if p.get("currency", {}).get("type") == "cryptocurrency"})\n                                args = {}\n                                for key in props:\n                                    if norm(key) == "symbols": args[key] = symbols\n                                    elif norm(key) == "rhsaccountnumber":\n                                        args[key] = field(account, "rhsaccountnumber")\n                                if set(qs.get("required", [])) - set(args):\n                                    raise RuntimeError("Unsupported quote schema")\n                                if symbols:\n                                    response = await call("getcryptoquotes", args)\n                                    if not isinstance(response.get("results"), list):\n                                        raise RuntimeError("Invalid quote response")\n                                    quotes = [pick(q, ("symbol", "bid_price", "ask_price", "mark_price", "updated_at"))\n                                              for q in response["results"]]\n                            except Exception as exc:\n                                quote_error = type(exc).__name__\n'


def write(path,text,meta):
    fd,tmp=tempfile.mkstemp(dir=str(path.parent),prefix='.accounting-')
    try:
        with os.fdopen(fd,'w') as f:f.write(text);f.flush();os.fsync(f.fileno())
        os.chown(tmp,meta.st_uid,meta.st_gid);os.chmod(tmp,meta.st_mode & 0o777)
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def gitsha(raw):return hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()

def main():
    if os.geteuid()!=0:raise SystemExit('Run with sudo python3.')
    expected={HTML:'a08dcf6cf362f8945601023f7d85a616f5298406',COLLECTOR:'2a95e907aa41f380bddea3c7deccf6df62b05c22'}
    for p,sha in expected.items():
        if not p.is_file() or gitsha(p.read_bytes())!=sha:
            raise SystemExit('STOP: installed file differs from reviewed GitHub upload: '+str(p)+'. Nothing changed.')
    if MODULE.exists():raise SystemExit('STOP: accounting module already exists. Nothing changed.')
    subprocess.run(['systemctl','is-active','--quiet',SERVICE],check=True)
    h=HTML.read_text(); c=COLLECTOR.read_text()
    if h.count('</body>')!=1:raise SystemExit('STOP: HTML structure not recognized.')
    # Retain the base application, status badges and live worker panel.
    # Replace supplementary scripts with one direct-data accounting renderer.
    spans=list(re.finditer(r'<script\b[^>]*>.*?</script\s*>',h,re.S|re.I))
    if not spans or 'const defs=' not in spans[0].group():raise SystemExit('STOP: base application not recognized.')
    removed=0
    for m in reversed(spans[1:]):
        script=m.group()
        if '/api/v1/workers/crypto' in script or '/api/v1/status' in script:continue
        h=h[:m.start()]+h[m.end():];removed+=1
    h=h.replace('</body>',JS+'\n</body>',1)
    required=['id="dashboard-page"','id="positions-page"','id="trades-page"']
    if not all(x in h for x in required):raise SystemExit('STOP: required page sections missing.')
    anchor='                        snapshot["bots"][bot] = {'
    if c.count(anchor)!=1:raise SystemExit('STOP: collector assignment not unique.')
    c=c.replace(anchor,QUOTES+anchor,1)
    anchor='                            "orders": safe_orders,'
    if c.count(anchor)!=1:raise SystemExit('STOP: collector schema differs.')
    c=c.replace(anchor,anchor+'\n                            "quotes": quotes,\n                            "quote_error": quote_error,',1)
    c=c.replace('def publish(data):','def publish(data):\n    data["accounting_v2"] = build(data)',1)
    c='from dashboard_accounting_v2 import build\n'+c
    ast.parse(c);ast.parse(MODULE_TEXT)
    namespace={};exec(compile(MODULE_TEXT,'accounting','exec'),namespace)
    sample={'status':'READ_OK','positions':[],'orders':[
      {'id':'b','currency_code':'BTC','side':'buy','state':'filled','cumulative_quantity':'2','average_price':'49','net_rounded_executed_notional':'100','fee':'2','created_at':'2026-10-30T01:00:00-04:00'},
      {'id':'s','currency_code':'BTC','side':'sell','state':'filled','cumulative_quantity':'1','average_price':'61','net_rounded_executed_notional':'60','fee':'1','created_at':'2026-10-30T02:00:00-04:00'}]}
    test=namespace['calculate'](sample,True,None,'2026-10-30')
    assert test['trades'][0]['net']=='10.0',test
    assert test['trades'][0]['actual_total']=='50.0',test
    assert test['trades'][0]['buy_fee']=='1.0',test
    sample['orders'][0].pop('net_rounded_executed_notional')
    assert namespace['calculate'](sample,True,None,'2026-10-30')['trades'][0]['net'] is None
    if not FEED.is_file():raise SystemExit('STOP: collector snapshot absent.')
    json.loads(FEED.read_text())
    stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup=ROOT/('accounting-backup-'+stamp);backup.mkdir(mode=0o700)
    for p in (HTML,COLLECTOR,FEED):shutil.copy2(p,backup/p.name)
    originals={p:(p.read_text(),p.stat()) for p in (HTML,COLLECTOR,FEED)}
    stopped=False
    try:
        subprocess.run(['systemctl','stop',SERVICE],check=True);stopped=True
        # Refresh rollback snapshot after the collector has fully stopped.
        originals[FEED]=(FEED.read_text(),FEED.stat());shutil.copy2(FEED,backup/FEED.name)
        write(MODULE,MODULE_TEXT,COLLECTOR.stat())
        write(COLLECTOR,c,COLLECTOR.stat());write(HTML,h,HTML.stat())
        snapshot=json.loads(FEED.read_text());snapshot['accounting_v2']=namespace['build'](snapshot)
        write(FEED,json.dumps(snapshot,allow_nan=False),FEED.stat())
        subprocess.run(['systemctl','start',SERVICE],check=True)
        subprocess.run(['systemctl','is-active','--quiet',SERVICE],check=True)
        with urlopen('http://127.0.0.1:8000/api/v1/live',timeout=10) as r:returned=json.load(r)
        assert returned.get('accounting_v2',{}).get('version')==2,'API did not return accounting data'
        with urlopen('http://127.0.0.1:8000/',timeout=10) as r:assert b'SI_ACCOUNTING_DIRECT_V2' in r.read()
    except Exception:
        if stopped:subprocess.run(['systemctl','stop',SERVICE],check=False)
        for p,(text,meta) in originals.items():write(p,text,meta)
        MODULE.unlink(missing_ok=True)
        if stopped:subprocess.run(['systemctl','start',SERVICE],check=False)
        print('Install failed. Original files and snapshot restored.');raise
    print('INSTALLED: direct-data position tables, FIFO closed trades and accounting cards.')
    print('Partial-sale allocation and no-double-fee tests passed.')
    print('HTTP checks passed; browser rendering and new live quotes still require verification.')
    print('Wait for the collector refresh (normally about 1-4 minutes), then hard-refresh Chrome.')
    print('Only the read-only collector restarted. No trading worker restarted or resumed.')
    print('Exit fees are estimates only when the existing planning fee allowance is available.')
    print('Accounting scope is selected asset class in the brokerage account, not worker attribution.')
    print('Backups:',backup)

if __name__=='__main__':main()
